const $=(q,r=document)=>r.querySelector(q), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.head.insertAdjacentHTML('beforeend',`<style>.chart{padding:8px 0}.bar-row{display:grid;grid-template-columns:130px 1fr 90px;gap:10px;align-items:center;margin:12px 0;font-size:12px}.bar-row i{height:10px;background:#e6eee9;border-radius:99px;overflow:hidden}.bar-row i b{display:block;height:100%;background:#16855d;border-radius:99px}.bar-row strong{text-align:right}.invoice-calendar{margin:12px 0 18px}.invoice-calendar h3{margin:0 0 8px}.calendar-head,.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr)}.calendar-head b{text-align:center;padding:5px;background:#eaf4ef;font-size:10px}.cal{min-height:43px;border:1px solid #dce5e0;padding:4px;display:flex;flex-direction:column}.cal b{font-size:10px}.cal span{font-size:9px;text-align:center;margin-top:auto}.cal.served{background:#e8f7ef;color:#075d43}.cal.blank{background:#f7f8f7}@media(max-width:760px){.bar-row{grid-template-columns:90px 1fr 75px}}@media print{.invoice-calendar{break-inside:avoid}.calendar-head b,.cal{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style>`);
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}), monthNow=()=>today().slice(0,7);
const icon=(name)=>({dashboard:'⌂',daily:'▣',customers:'♟',payments:'▤',inventory:'▰',billing:'▧',reports:'▥',drivers:'◆',settings:'⚙'}[name]||'•');
const seed={version:2,business:{name:'My RO Water Plant',phone:'',address:'',upi:'',gstin:'',invoicePrefix:'RO',nextInvoice:1,defaultRate:25,defaultDiscount:0,language:'English'},customers:[],deliveries:{},monthlyPending:{},invoiceExtras:{},payments:[],expenses:[],inventory:{full:0,empty:0,damaged:0,atCustomers:0},staff:[],billingRuns:{},notes:{},updatedAt:null};
let db=structuredClone(seed),page='dashboard',selectedDate=today(),selectedMonth=monthNow(),search='',supplySearch='',supplyFrom=`${monthNow()}-01`,supplyTo=today(),reportFrom=`${monthNow()}-01`,reportTo=today(),installPrompt=null,saveTimer=null;
let attendanceFrom=`${monthNow()}-01`,attendanceTo=`${monthNow()}-${String(new Date(+monthNow().slice(0,4),+monthNow().slice(5,7),0).getDate()).padStart(2,'0')}`,attendanceFocus=false;
async function api(method='GET'){let opt={method,headers:{'Content-Type':'application/json'}};if(method==='PUT')opt.body=JSON.stringify({...db,updatedAt:new Date().toISOString()});let r=await fetch('/api/water-data',opt);if(r.status===401){location.href='/login';return}let j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
async function load(){try{let j=await api();if(j?.data)db=merge(seed,j.data)}catch(e){toast(e.message,true)}render()}
function merge(a,b){let out={...structuredClone(a),...b};out.business={...a.business,...(b.business||{})};out.inventory={...a.inventory,...(b.inventory||{})};for(let k of ['customers','payments','expenses','staff'])if(!Array.isArray(out[k]))out[k]=[];for(let k of ['deliveries','monthlyPending','invoiceExtras','billingRuns'])if(!out[k]||typeof out[k]!=='object')out[k]={};return out}
function persist(now=false){clearTimeout(saveTimer);let run=async()=>{try{await api('PUT');status('Saved')}catch(e){status('Save failed');toast(e.message,true)}};if(now)run();else saveTimer=setTimeout(run,500)}
function status(text){let el=$('#syncStatus');if(el)el.textContent=text}
function toast(text,error=false){let el=$('#toast');el.textContent=text;el.style.background=error?'#7d2420':'#10271f';el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function activeCustomers(){return db.customers.filter(c=>c.active!==false)}
function dayRows(date=selectedDate){let day=db.deliveries[date]||{};return activeCustomers().map(c=>({customer:c,entry:{supplied:false,qty:0,returned:0,payment:0,status:'Pending',notes:'',...(day[c.id]||{})}}))}
function invoiceExtra(customer,month=selectedMonth){let x=db.invoiceExtras?.[month]?.[customer.id]||{};return{lines:Array.isArray(x.lines)?x.lines:[],note:x.note||''}}
function billNo(c,month=selectedMonth){db.billNumbers??={};const m=db.billNumbers[month]??={};if(!m[c.id]){m[c.id]=`${db.business.invoicePrefix||'RO'}-${month.replace('-','')}-${String(+db.business.nextInvoice||1).padStart(4,'0')}`;db.business.nextInvoice=(+db.business.nextInvoice||1)+1;persist()}return m[c.id]}
function account(customer,month=selectedMonth){let supplied=0,returned=0,charge=0,paid=0,days=0;for(let [date,day] of Object.entries(db.deliveries)){if(!date.startsWith(month)||!day[customer.id])continue;let e=day[customer.id];if(e.supplied){days++;supplied+=+e.qty||0;returned+=+e.returned||0;charge+=(+e.qty||0)*(+e.rate||+customer.rate||+db.business.defaultRate||0);paid+=+e.payment||0}}paid+=db.payments.filter(p=>p.customerId===customer.id&&p.date.startsWith(month)).reduce((a,p)=>a+(+p.amount||0),0);let extras=invoiceExtra(customer,month),extrasTotal=extras.lines.reduce((s,x)=>s+(+x.amount||0),0),savedPending=db.monthlyPending?.[month]?.[customer.id],opening=savedPending===undefined?(+customer.opening||0):(+savedPending||0),snap=db.billingRuns?.[month]?.snap?.[customer.id],discount=Math.min(charge+extrasTotal,snap?(+snap.discount||0):(+customer.discount||+db.business.defaultDiscount||0)),taxable=Math.max(0,charge+extrasTotal-discount),gstRate=snap?(snap.gstBilling?(+snap.gstRate||0):0):(customer.gstBilling?(+customer.gstRate||0):0),gstAmount=taxable*gstRate/100,total=taxable+gstAmount;return{days,supplied,returned,charge,extras,extrasTotal,discount,taxable,gstRate,gstAmount,total,paid,opening,balance:opening+total-paid,jarsDue:Math.max(0,(+customer.jarsDue||0)+supplied-returned)}}
function inRange(date,from,to){return(!from||date>=from)&&(!to||date<=to)}
function rangeAccount(customer,from,to){let days=0,jars=0,revenue=0;for(let [date,day] of Object.entries(db.deliveries)){let e=day[customer.id];if(!e?.supplied||!inRange(date,from,to))continue;days++;jars+=+e.qty||0;revenue+=(+e.qty||0)*(+e.rate||+customer.rate||+db.business.defaultRate||0)}return{days,jars,revenue}}
function todayStats(){let rows=dayRows(),delivered=rows.filter(x=>x.entry.supplied),qty=delivered.reduce((a,x)=>a+(+x.entry.qty||0),0),returned=delivered.reduce((a,x)=>a+(+x.entry.returned||0),0),collection=rows.reduce((a,x)=>a+(+x.entry.payment||0),0),outstanding=activeCustomers().reduce((a,c)=>a+Math.max(0,account(c).balance),0);return{delivered:delivered.length,regular:rows.length,qty,returned,collection,outstanding,due:activeCustomers().reduce((a,c)=>a+account(c).jarsDue,0)}}
const nav=[['dashboard','Dashboard'],['daily','Daily Supply'],['customers','Customers'],['payments','Payments'],['inventory','Jar Inventory'],['billing','Monthly Billing'],['reports','Reports'],['drivers','Drivers'],['settings','Settings']];
function shell(){return `<div class="shell"><aside class="sidebar"><div class="brand">i<span>♥</span>invoice<i>.net</i></div><div class="module-label"><b>Water Plant</b><small>RO supply operations</small></div><nav class="nav">${nav.map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}"><span>${icon(k)}</span>${v}</button>`).join('')}</nav><div class="side-foot">Separate business module<br><a href="/app">← General invoicing</a></div></aside><main class="main"><header class="topbar"><div><h1>Water Plant</h1><p>${esc(db.business.name)}</p></div><div class="top-actions"><span id="syncStatus" class="hide-mobile" style="align-self:center;color:var(--muted);font-size:12px">Synced</span><button class="btn" data-action="install">↓ Install App</button><nav class="ws-switch" aria-label="Workspace" data-testid="workspace-switcher"><a href="/app" data-testid="switch-to-general">General</a><a class="active" href="/water-plant" aria-current="page">Water Plant</a></nav><button class="btn hide-mobile" data-action="logout" data-testid="logout-btn">Sign out</button></div></header><div class="content">${view()}</div></main><nav class="mobile-nav">${[['dashboard','Home'],['daily','Supply'],['customers','Customers'],['payments','Payments'],['billing','Billing'],['settings','Settings']].map(([k,v])=>`<button data-page="${k}" class="${page===k?'active':''}"><b>${icon(k)}</b>${v}</button>`).join('')}</nav></div>`}
function heading(title,desc,actions=''){return `<div class="pagehead"><div><h2>${title}</h2><p>${desc}</p></div><div class="actions no-print">${actions}</div></div>`}
function metrics(s){return `<div class="metrics"><div class="metric"><label>Deliveries today</label><strong>${s.delivered} <small>/ ${s.regular}</small></strong><small>Regular customers</small></div><div class="metric"><label>Jars supplied</label><strong>${s.qty}</strong><small>20L jars today</small></div><div class="metric"><label>Outstanding balance</label><strong>${money(s.outstanding)}</strong><small>Across active customers</small></div><div class="metric"><label>Empty jars due</label><strong>${s.due}</strong><small>To be collected</small></div></div>`}
function dashboard(){let s=todayStats(),recent=activeCustomers().slice(0,7);return `${heading("Today's operations",new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}),`<button class="btn" data-page="customers">＋ Add customer</button><button class="btn primary" data-page="daily">Open daily register</button>`)}${metrics(s)}<div class="grid2"><section class="panel"><div class="panel-head"><h3>Today's delivery overview</h3><span class="spacer"></span><button class="btn small" data-page="daily">Manage supply</button></div>${recent.length?`<div class="table-wrap"><table><thead><tr><th>Customer</th><th>Route</th><th>Jars</th><th>Returned</th><th>Collection</th><th>Status</th></tr></thead><tbody>${dayRows().slice(0,10).map(({customer:c,entry:e})=>`<tr><td class="customer"><b>${esc(c.name)}</b><small>${esc(c.phone||'No phone')}</small></td><td>${esc(c.route||'Unassigned')}</td><td>${e.qty}</td><td>${e.returned}</td><td>${money(e.payment)}</td><td><span class="tag ${e.supplied?'ok':'pending'}">${e.supplied?'Completed':'Pending'}</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">Add customers to begin daily water delivery tracking.</div>`}</section><aside><section class="panel"><div class="panel-head"><h3>Today's totals</h3></div><div class="summary"><div class="summary-row"><span>Delivered</span><b>${s.delivered}</b></div><div class="summary-row"><span>Jars supplied</span><b>${s.qty}</b></div><div class="summary-row"><span>Empty returned</span><b>${s.returned}</b></div><div class="summary-row"><span>Collection</span><b>${money(s.collection)}</b></div></div></section><section class="panel" style="margin-top:15px"><div class="panel-head"><h3>Quick note</h3></div><div style="padding:15px"><textarea id="dailyNote" style="width:100%;min-height:85px;border:1px solid var(--line);border-radius:8px;padding:10px" placeholder="Special requests, absent customers…">${esc(db.notes[selectedDate]||'')}</textarea><button class="btn small" data-action="save-note" style="margin-top:8px">Save note</button></div></section></aside></div>`}
function daily(){let all=activeCustomers(),customers=all.filter(c=>`${c.name} ${c.phone||''}`.toLowerCase().includes(supplySearch.toLowerCase())),[year,month]=selectedMonth.split('-').map(Number),days=new Date(year,month,0).getDate(),dayNumbers=Array.from({length:days},(_,i)=>i+1),stats=customers.map(c=>({c,...rangeAccount(c,supplyFrom,supplyTo)})),max=Math.max(1,...stats.map(x=>x.jars));return `${heading('Monthly supply register',`All customers and days 1–${days} on one attendance-style sheet. Use − / + to update jars.`,`<button class="btn primary" data-action="save-now">Save register</button>`)}<div class="filter-strip"><label>Search customer<input id="supplySearch" type="search" placeholder="Name or phone" value="${esc(supplySearch)}"></label><label>Attendance from<input id="supplyFrom" type="date" value="${supplyFrom}"></label><label>To<input id="supplyTo" type="date" value="${supplyTo}"></label></div><section class="panel attendance-chart"><div class="panel-head"><div><h3>Attendance chart</h3><small>${supplyFrom} to ${supplyTo}</small></div></div><div class="chart">${stats.map(x=>`<div class="bar-row"><span>${esc(x.c.name)}<small>${x.days} days</small></span><i><b style="width:${Math.max(2,x.jars/max*100)}%"></b></i><strong>${x.jars} jars</strong></div>`).join('')||'<div class="empty">No supply found in this date range.</div>'}</div></section><section class="panel monthly-register"><div class="panel-head"><div><h3>Jar attendance · ${new Date(year,month-1,1).toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</h3><small>Customer stays on the left; total and old pending stay visible on the right</small></div><span class="spacer"></span><input type="month" id="monthPicker" value="${selectedMonth}"></div>${customers.length?`<div class="month-grid-wrap"><table class="month-grid"><thead><tr><th class="sticky-customer">Customer</th>${dayNumbers.map(d=>`<th>${d}</th>`).join('')}<th class="month-total">Total</th><th class="pending-col">Old pending</th></tr></thead><tbody>${customers.map(c=>{let total=0,cells=dayNumbers.map(d=>{let date=`${selectedMonth}-${String(d).padStart(2,'0')}`,e=db.deliveries[date]?.[c.id],qty=e?.supplied?(+e.qty||0):0;total+=qty;return `<td class="month-cell ${qty?'has-supply':''}"><button data-action="month-step" data-date="${date}" data-id="${c.id}" data-delta="-1">−</button><b>${qty}</b><button data-action="month-step" data-date="${date}" data-id="${c.id}" data-delta="1">＋</button></td>`}).join(''),pending=account(c).opening;return `<tr><td class="sticky-customer customer"><b>${esc(c.name)}</b><small>${esc(c.phone||'')}</small></td>${cells}<td class="month-total">${total}</td><td class="pending-col"><input class="pending-input" type="number" min="0" step="1" inputmode="decimal" data-month-pending="${c.id}" value="${pending}" aria-label="Old pending amount for ${esc(c.name)}"></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">No matching active customers.</div>`}</section>`}
function attendanceDays(){const [year,month]=selectedMonth.split('-').map(Number),days=new Date(year,month,0).getDate();return Array.from({length:days},(_,i)=>i+1).filter(day=>{const date=`${selectedMonth}-${String(day).padStart(2,'0')}`;return inRange(date,attendanceFrom,attendanceTo)})}
function visibleAttendanceTotal(id){return attendanceDays().reduce((sum,day)=>{const date=`${selectedMonth}-${String(day).padStart(2,'0')}`,entry=db.deliveries[date]?.[id];return sum+(entry?.supplied?(+entry.qty||0):0)},0)}
function dailyRegister(){const customers=activeCustomers().filter(c=>`${c.name} ${c.phone||''}`.toLowerCase().includes(supplySearch.toLowerCase())),[year,month]=selectedMonth.split('-').map(Number),days=attendanceDays(),last=`${selectedMonth}-${String(new Date(year,month,0).getDate()).padStart(2,'0')}`,stats=customers.map(c=>({c,...rangeAccount(c,supplyFrom,supplyTo)})),max=Math.max(1,...stats.map(x=>x.jars));return `${heading('Monthly supply register','Update each customer’s jars by date. Open the register for a clear, full-screen view.',`<button class="btn primary" data-action="save-now">Save register</button>`)}<div class="filter-strip"><label>Search customer<input id="supplySearch" type="search" placeholder="Name or phone" value="${esc(supplySearch)}"></label><label>Chart from<input id="supplyFrom" type="date" value="${supplyFrom}"></label><label>Chart to<input id="supplyTo" type="date" value="${supplyTo}"></label></div><section class="panel attendance-chart"><div class="panel-head"><div><h3>Attendance chart</h3><small>${supplyFrom} to ${supplyTo}</small></div></div><div class="chart">${stats.map(x=>`<div class="bar-row"><span>${esc(x.c.name)}<small>${x.days} days</small></span><i><b style="width:${Math.max(2,x.jars/max*100)}%"></b></i><strong>${x.jars} jars</strong></div>`).join('')||'<div class="empty">No supply found in this date range.</div>'}</div></section><section class="panel monthly-register"><div class="panel-head attendance-toolbar"><div class="attendance-title"><h3>Jar attendance · ${new Date(year,month-1,1).toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</h3><small>Visible dates: ${attendanceFrom} to ${attendanceTo} · ${days.length} day${days.length===1?'':'s'}</small></div><div class="attendance-controls"><label>Month<input type="month" id="monthPicker" value="${selectedMonth}"></label><label>From<input type="date" id="attendanceFrom" min="${selectedMonth}-01" max="${last}" value="${attendanceFrom}"></label><label>To<input type="date" id="attendanceTo" min="${selectedMonth}-01" max="${last}" value="${attendanceTo}"></label><button class="btn small" data-action="attendance-today">Today</button><button class="btn small attendance-expand" data-action="attendance-focus">⛶ Full screen</button><button class="btn small attendance-exit" data-action="attendance-exit">✕ Exit</button></div></div>${customers.length?`<div class="month-grid-wrap"><table class="month-grid"><thead><tr><th class="sticky-customer">Customer</th>${days.map(d=>`<th>${d}</th>`).join('')}<th class="month-total">Visible total</th><th class="pending-col">Old pending</th></tr></thead><tbody>${customers.map(c=>{const cells=days.map(d=>{const date=`${selectedMonth}-${String(d).padStart(2,'0')}`,entry=db.deliveries[date]?.[c.id],qty=entry?.supplied?(+entry.qty||0):0;return `<td class="month-cell ${qty?'has-supply':''}"><button data-action="month-step" data-date="${date}" data-id="${c.id}" data-delta="-1" aria-label="Remove jar for ${esc(c.name)} on ${date}">−</button><b>${qty}</b><button data-action="month-step" data-date="${date}" data-id="${c.id}" data-delta="1" aria-label="Add jar for ${esc(c.name)} on ${date}">＋</button></td>`}).join('');return `<tr><td class="sticky-customer customer"><b>${esc(c.name)}</b><small>${esc(c.phone||'')}</small></td>${cells}<td class="month-total">${visibleAttendanceTotal(c.id)}</td><td class="pending-col"><input class="pending-input" type="number" min="0" step="1" inputmode="decimal" data-month-pending="${c.id}" value="${account(c).opening}" aria-label="Old pending amount for ${esc(c.name)}"></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty">No matching active customers.</div>`}</section>`}
function stepper(id,key,val){return `<span class="stepper"><button data-action="step" data-id="${id}" data-key="${key}" data-delta="-1">−</button><input type="number" min="0" data-entry="${key}" data-id="${id}" value="${val}"><button data-action="step" data-id="${id}" data-key="${key}" data-delta="1">＋</button></span>`}
function customers(){let items=activeCustomers().filter(c=>c.name.toLowerCase().includes(search.toLowerCase()));return `${heading('Customers','Save details once, then update only daily quantity.',`<button class="btn primary" data-action="customer-modal">＋ Add customer</button>`)}<div class="toolbar" style="margin-bottom:15px"><input type="search" id="search" placeholder="Search customer" value="${esc(search)}"><button class="btn" data-action="export-customers">Export CSV</button></div><div class="cards">${items.map(c=>{let a=account(c);return `<article class="customer-card"><h3>${esc(c.name)}</h3><p>${esc(c.phone||'No phone')} · ${esc(c.route||'No route')}</p><p>${esc(c.address||'No address')}</p><div class="balance"><span>Balance <b>${money(a.balance)}</b></span><span>Jars due <b>${a.jarsDue}</b></span></div><div class="actions" style="margin-top:14px"><button class="btn small" data-action="customer-modal" data-id="${c.id}">Edit</button><button class="btn small" data-action="ledger" data-id="${c.id}">Ledger</button><button class="btn small danger" data-action="delete-customer" data-id="${c.id}">Delete</button></div></article>`}).join('')||'<div class="empty panel">No customers found.</div>'}</div>`}
function payments(){let monthPayments=db.payments.filter(p=>p.date.startsWith(selectedMonth)),total=monthPayments.reduce((a,p)=>a+(+p.amount||0),0),advance=monthPayments.filter(p=>p.kind==='Advance').reduce((a,p)=>a+(+p.amount||0),0);return `${heading('Payments & advance wallet','Record advance, partial, cash, UPI and bank payments.',`<button class="btn primary" data-action="payment-modal">＋ Record payment</button>`)}<div class="metrics"><div class="metric"><label>This month collected</label><strong>${money(total)}</strong><small>${monthPayments.length} receipts</small></div><div class="metric"><label>Advance received</label><strong>${money(advance)}</strong><small>Customer prepaid wallet</small></div><div class="metric"><label>Total outstanding</label><strong>${money(activeCustomers().reduce((a,c)=>a+Math.max(0,account(c).balance),0))}</strong><small>Current month</small></div></div><section class="panel"><div class="panel-head"><h3>Payment history</h3><span class="spacer"></span><input type="month" id="monthPicker" value="${selectedMonth}"></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Customer</th><th>Type</th><th>Method</th><th>Reference</th><th>Amount</th></tr></thead><tbody>${monthPayments.map(p=>`<tr><td>${p.date}</td><td>${esc(activeCustomers().find(c=>c.id===p.customerId)?.name||'Deleted customer')}</td><td><span class="tag ok">${esc(p.kind||'Payment')}</span></td><td>${esc(p.method)}</td><td>${esc(p.reference||'—')}</td><td><b>${money(p.amount)}</b></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No payments in this month.</td></tr>'}</tbody></table></div></section>`}
function inventory(){let i=db.inventory;return `${heading('Jar inventory','Track full, empty, damaged and customer-held jars.',`<button class="btn primary" data-action="save-inventory">Save inventory</button>`)}<div class="metrics">${[['Full jars','full'],['Empty jars','empty'],['Damaged jars','damaged'],['At customers','atCustomers']].map(([l,k])=>`<div class="metric"><label>${l}</label><strong><input type="number" min="0" data-inventory="${k}" value="${i[k]}" style="width:110px;border:0;font-size:25px;font-weight:800"></strong><small>Current physical count</small></div>`).join('')}</div><section class="panel"><div class="panel-head"><h3>Customer jar liability</h3></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Opening jars</th><th>Supplied this month</th><th>Returned</th><th>Currently due</th></tr></thead><tbody>${activeCustomers().map(c=>{let a=account(c);return `<tr><td>${esc(c.name)}</td><td>${+c.jarsDue||0}</td><td>${a.supplied}</td><td>${a.returned}</td><td><b>${a.jarsDue}</b></td></tr>`}).join('')}</tbody></table></div></section>`}
function billing(){let rows=activeCustomers().map(c=>({c,a:account(c)})),run=db.billingRuns[selectedMonth];return `${heading('Monthly billing','Generate all invoices or customise and print one customer invoice.',`<button class="btn" data-action="export-month">Export CSV</button><button class="btn" data-action="master-excel">Master Excel</button><button class="btn primary" data-action="generate-bills">${run?'Refresh':'Generate all'} bills</button><button class="btn primary" data-action="print-all">Print / PDF all</button>`)}${run?`<div class="notice" style="margin-bottom:14px">Bills generated on ${new Date(run.generatedAt).toLocaleString('en-IN')} for ${run.count} customers.</div>`:''}<section class="panel"><div class="panel-head"><h3>Billing run</h3><span class="spacer"></span><input type="month" id="monthPicker" value="${selectedMonth}"></div><div class="table-wrap"><table><thead><tr><th>Customer</th><th>Supply days</th><th>Total jars</th><th>Current amount</th><th>Extra lines</th><th>Old pending</th><th>Paid</th><th>Status / balance</th><th>Actions</th></tr></thead><tbody>${rows.map(({c,a})=>`<tr><td class="customer"><b>${esc(c.name)}</b><small>${esc(c.phone||'')} · ${c.gstBilling?'GST invoice':'Regular invoice'}</small></td><td>${a.days}</td><td>${a.supplied}</td><td>${money(a.charge)}</td><td>${money(a.extrasTotal)}</td><td>${money(a.opening)}</td><td>${money(a.paid)}</td><td><span class="tag ${a.balance<=0?'ok':'pending'}">${a.balance<=0?'Paid':'Unpaid'}</span> <b>${money(a.balance)}</b></td><td><button class="btn small" data-action="invoice-extra" data-id="${c.id}">Edit invoice</button> <button class="btn small" data-action="print-one" data-id="${c.id}">Invoice</button> <button class="btn small" data-action="whatsapp" data-id="${c.id}">WhatsApp</button></td></tr>`).join('')||'<tr><td colspan="9" class="empty">Add customers first.</td></tr>'}</tbody></table></div></section><div id="printArea" class="print-only"></div>`}
function duesAging(){let buckets=[0,0,0,0];for(let c of activeCustomers()){let bal=Math.max(0,account(c).balance);if(!bal)continue;let age=+c.pendingAge||0;buckets[age>90?3:age>60?2:age>30?1:0]+=bal}return buckets}
function analyticsBars(rows){let vals=rows.map(x=>x.a.charge),max=Math.max(1,...vals);return `<div class="chart">${rows.slice(0,12).map(x=>`<div class="bar-row"><span>${esc(x.c.name)}</span><i><b style="width:${Math.max(2,x.a.charge/max*100)}%"></b></i><strong>${money(x.a.charge)}</strong></div>`).join('')||'<div class="empty">No billing data.</div>'}</div>`}
function reports(){let customers=activeCustomers(),rows=customers.map(c=>({c,a:account(c)})),rangeRows=customers.map(c=>({c,...rangeAccount(c,reportFrom,reportTo)})),rangeRevenue=rangeRows.reduce((s,x)=>s+x.revenue,0),rangeJars=rangeRows.reduce((s,x)=>s+x.jars,0),currentRevenue=rows.reduce((s,x)=>s+x.a.charge+x.a.extrasTotal-x.a.discount,0),pending=rows.reduce((s,x)=>s+Math.max(0,x.a.balance),0),col=rows.reduce((s,x)=>s+x.a.paid,0),months=Array.from({length:6},(_,i)=>{let d=new Date(+selectedMonth.slice(0,4),+selectedMonth.slice(5,7)-1-(5-i),1),m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;return{m,v:customers.reduce((s,c)=>{let a=account(c,m);return s+a.charge+a.extrasTotal-a.discount},0)}}),maxMonth=Math.max(1,...months.map(x=>x.v)),maxPending=Math.max(1,...rows.map(x=>Math.max(0,x.a.balance))),out=[...rows].sort((x,y)=>y.a.balance-x.a.balance).slice(0,8);return `${heading('Reports & analytics','Revenue, pending balances and month-on-month performance.',`<button class="btn" data-action="master-excel">Download Master Excel</button>`)}<div class="filter-strip"><label>Report from<input id="reportFrom" type="date" value="${reportFrom}"></label><label>To<input id="reportTo" type="date" value="${reportTo}"></label></div><div class="metrics"><div class="metric"><label>Current month revenue</label><strong>${money(currentRevenue)}</strong><small>${selectedMonth}</small></div><div class="metric"><label>Selected range revenue</label><strong>${money(rangeRevenue)}</strong><small>${reportFrom} to ${reportTo}</small></div><div class="metric"><label>Selected range jars</label><strong>${rangeJars}</strong><small>Delivered jars</small></div><div class="metric"><label>Current pending</label><strong>${money(pending)}</strong><small>All customer balances</small></div></div><div class="grid2"><section class="panel report"><h3>Month-on-month revenue</h3><div class="chart">${months.map(x=>`<div class="bar-row"><span>${x.m}</span><i><b style="width:${Math.max(2,x.v/maxMonth*100)}%"></b></i><strong>${money(x.v)}</strong></div>`).join('')}</div></section><section class="panel report"><h3>Pending by customer</h3><div class="chart">${out.map(x=>`<div class="bar-row"><span>${esc(x.c.name)}</span><i class="pending-bar"><b style="width:${Math.max(2,Math.max(0,x.a.balance)/maxPending*100)}%"></b></i><strong>${money(Math.max(0,x.a.balance))}</strong></div>`).join('')||'<div class="empty">No pending balance.</div>'}</div></section></div><div class="grid2" style="margin-top:15px"><section class="panel report"><h3>Revenue by customer · selected range</h3><div class="chart">${rangeRows.map(x=>`<div class="bar-row"><span>${esc(x.c.name)}</span><i><b style="width:${Math.max(2,x.revenue/Math.max(1,...rangeRows.map(r=>r.revenue))*100)}%"></b></i><strong>${money(x.revenue)}</strong></div>`).join('')}</div></section><section class="panel report"><h3>Current month collections</h3><div class="summary-row"><span>Revenue billed</span><b>${money(currentRevenue)}</b></div><div class="summary-row"><span>Payments recorded</span><b>${money(col)}</b></div><div class="summary-row"><span>Pending</span><b>${money(pending)}</b></div><button class="btn small" data-action="export-dues" style="margin-top:12px">Export dues report</button></section></div>`}
function drivers(){return `${heading('Drivers & staff','Keep delivery staff access details separate.',`<button class="btn primary" data-action="driver-modal">＋ Add driver</button>`)}<div class="cards">${db.staff.map(d=>`<article class="customer-card"><h3>${esc(d.name)}</h3><p>${esc(d.phone||'No phone')}</p><p>Login PIN: ••••</p><div class="balance"><span>Status <b>${d.active===false?'Disabled':'Active'}</b></span></div><div class="actions" style="margin-top:14px"><button class="btn small" data-action="driver-modal" data-id="${d.id}">Edit</button><button class="btn small" data-action="toggle-driver" data-id="${d.id}">${d.active===false?'Enable':'Disable'}</button></div></article>`).join('')||'<div class="empty panel">No drivers added.</div>'}</div>`}
function settings(){let b=db.business;return `${heading('Water Plant settings','These settings stay separate from general invoicing.',`<button class="btn primary" data-action="save-settings">Save settings</button>`)}<div class="settings-sections"><section class="panel"><div class="panel-head"><h3>Business & seller GST details</h3></div><form id="settingsForm" class="form-grid" style="padding:18px"><div class="field"><label>Plant / business name</label><input name="name" value="${esc(b.name)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(b.phone)}"></div><div class="field full"><label>Seller address</label><textarea name="address">${esc(b.address)}</textarea></div><div class="field"><label>Seller GSTIN</label><input name="gstin" maxlength="15" value="${esc(b.gstin)}" placeholder="15-character GSTIN"></div><div class="field"><label>Seller PAN</label><input name="pan" value="${esc(b.pan||'')}"></div><div class="field"><label>Seller state</label><input name="state" value="${esc(b.state||'')}"></div><div class="field"><label>Seller state code</label><input name="stateCode" maxlength="2" value="${esc(b.stateCode||'')}" placeholder="e.g. 09"></div><div class="field"><label>Seller email</label><input type="email" name="email" value="${esc(b.email||'')}"></div><div class="field"><label>Default 20L jar rate</label><input type="number" min="0" name="defaultRate" value="${b.defaultRate}"></div><div class="field"><label>Default flat discount</label><input type="number" min="0" name="defaultDiscount" value="${b.defaultDiscount||0}"></div><div class="field"><label>UPI ID</label><input name="upi" value="${esc(b.upi)}"></div><div class="field"><label>Invoice prefix</label><input name="invoicePrefix" value="${esc(b.invoicePrefix)}"></div><div class="field"><label>Interface language</label><select name="language">${['English','हिन्दी','ગુજરાતી','मराठी','ਪੰਜਾਬੀ','বাংলা','தமிழ்','తెలుగు','ಕನ್ನಡ','മലയാളം'].map(x=>`<option ${b.language===x?'selected':''}>${x}</option>`).join('')}</select></div></form></section><section class="panel"><div class="panel-head"><h3>Backup, notifications & app</h3></div><div style="padding:18px"><div class="notice">Records are stored account-wise and remain separate from general invoices.</div><div class="actions" style="margin-top:12px"><button class="btn" data-action="export-backup">Download JSON backup</button><label class="btn" data-testid="water-restore-label">Restore backup<input type="file" accept=".json,application/json" data-restore hidden data-testid="water-restore-input"></label><button class="btn" data-action="master-excel">Download Master Excel</button><button class="btn" data-action="notify">Enable push notifications</button><button class="btn" data-action="install">Install this app</button><button class="btn" data-action="logout" data-testid="settings-logout-btn">Sign out</button></div></div></section></div>`}
function view(){return ({dashboard,daily:dailyRegister,customers,payments,inventory,billing,reports,drivers,settings}[page]||dashboard)()}
function ensureDay(){return db.deliveries[selectedDate]||(db.deliveries[selectedDate]={})}
function entryFor(date,id){let day=db.deliveries[date]||(db.deliveries[date]={});return day[id]||(day[id]={supplied:false,qty:0,returned:0,payment:0,status:'Pending',notes:''})}
function entry(id){let d=ensureDay();return d[id]||(d[id]={supplied:false,qty:0,returned:0,payment:0,status:'Pending',notes:''})}
function render(){document.title=`${nav.find(x=>x[0]===page)?.[1]||'Water Plant'} · iluvinvoice.net`;document.body.classList.toggle('attendance-focus',page==='daily'&&attendanceFocus);$('#app').innerHTML=shell()}
function modal(title,body,foot=''){let d=$('#modal');$('#modalBody').innerHTML=`<div class="modal-head"><h2>${title}</h2></div><div class="modal-body">${body}</div><div class="modal-foot"><button class="btn" data-action="close-modal">Cancel</button>${foot}</div>`;d.showModal()}
function customerModal(id){let c=db.customers.find(x=>x.id===id)||{id:'',name:'',phone:'',address:'',rate:db.business.defaultRate,discount:0,opening:0,pendingAge:0,jarsDue:0,regularQty:1,gstBilling:false,customerGstin:'',gstRate:18,gstType:'CGST_SGST',state:'',active:true};modal(c.id?'Edit customer':'Add customer',`<form id="customerForm" class="form-grid"><input type="hidden" name="id" value="${c.id}"><div class="field"><label>Customer / company name</label><input required name="name" value="${esc(c.name)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(c.phone)}"></div><div class="field full"><label>Address</label><input name="address" value="${esc(c.address)}"></div><div class="field"><label>Rate per 20L jar</label><input type="number" min="0" name="rate" value="${c.rate}"></div><div class="field"><label>Regular daily quantity</label><input type="number" min="0" name="regularQty" value="${c.regularQty}"></div><div class="field"><label>Flat monthly discount</label><input type="number" min="0" name="discount" value="${c.discount||0}"></div><div class="field"><label>Opening pending amount</label><input type="number" name="opening" value="${c.opening}"></div><div class="field"><label>Pending age in days</label><input type="number" min="0" name="pendingAge" value="${c.pendingAge||0}"></div><div class="field"><label>Opening jars due</label><input type="number" min="0" name="jarsDue" value="${c.jarsDue}"></div><div class="field full gst-switch"><label><input type="checkbox" name="gstBilling" ${c.gstBilling?'checked':''}> Always generate GST invoice for this customer</label><small>Other customers will continue receiving the regular water bill.</small></div><div class="field"><label>Buyer GSTIN</label><input name="customerGstin" value="${esc(c.customerGstin||'')}" placeholder="Optional"></div><div class="field"><label>Buyer state</label><input name="state" value="${esc(c.state||'')}" placeholder="e.g. Uttar Pradesh"></div><div class="field"><label>Buyer state code</label><input name="stateCode" maxlength="2" value="${esc(c.stateCode||'')}" placeholder="e.g. 09"></div><div class="field"><label>Buyer PAN</label><input name="customerPan" value="${esc(c.customerPan||'')}"></div><div class="field"><label>Buyer email</label><input type="email" name="customerEmail" value="${esc(c.customerEmail||'')}"></div><div class="field"><label>GST rate (%)</label><input type="number" min="0" max="28" step="0.01" name="gstRate" value="${c.gstRate??18}"></div><div class="field"><label>Tax type</label><select name="gstType"><option value="CGST_SGST" ${c.gstType!=='IGST'?'selected':''}>CGST + SGST</option><option value="IGST" ${c.gstType==='IGST'?'selected':''}>IGST</option></select></div></form>`,`<button class="btn primary" data-action="submit-customer">Save customer</button>`)}
function paymentModal(){modal('Record payment',`<form id="paymentForm" class="form-grid"><div class="field full"><label>Customer</label><select required name="customerId"><option value="">Select customer</option>${activeCustomers().map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Date</label><input type="date" name="date" value="${today()}"></div><div class="field"><label>Amount</label><input required type="number" min="1" name="amount"></div><div class="field"><label>Payment type</label><select name="kind"><option>Payment</option><option>Advance</option><option>Old due settlement</option></select></div><div class="field"><label>Method</label><select name="method"><option>Cash</option><option>UPI</option><option>Bank</option><option>Cheque</option><option>Credit adjustment</option></select></div><div class="field"><label>Reference</label><input name="reference"></div></form>`,`<button class="btn primary" data-action="submit-payment">Save payment</button>`)}
function invoiceExtraModal(id){let c=db.customers.find(x=>x.id===id);if(!c)return;let x=invoiceExtra(c),text=x.lines.map(i=>`${i.description} | ${i.amount}`).join('\n');modal(`Customise invoice · ${esc(c.name)}`,`<form id="invoiceExtraForm" class="form-grid"><input type="hidden" name="customerId" value="${c.id}"><div class="field full"><label>Extra invoice lines</label><textarea name="lines" rows="6" placeholder="Delivery charge | 100&#10;Jar deposit | 200">${esc(text)}</textarea><small>One item per line: Description | Amount</small></div><div class="field full"><label>Additional note</label><textarea name="note" rows="3" placeholder="Optional note shown on this customer's invoice">${esc(x.note)}</textarea></div></form>`,`<button class="btn primary" data-action="save-invoice-extra">Save & generate</button>`)}
function driverModal(id){let d=db.staff.find(x=>x.id===id)||{id:'',name:'',phone:'',pin:'',active:true};modal(d.id?'Edit driver':'Add driver',`<form id="driverForm" class="form-grid"><input type="hidden" name="id" value="${d.id}"><div class="field"><label>Driver name</label><input required name="name" value="${esc(d.name)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(d.phone)}"></div><div class="field"><label>4-digit login PIN</label><input required pattern="[0-9]{4}" maxlength="4" name="pin" value="${esc(d.pin)}"></div></form>`,`<button class="btn primary" data-action="submit-driver">Save driver</button>`)}
function monthCalendar(c){let [y,m]=selectedMonth.split('-').map(Number),count=new Date(y,m,0).getDate(),cells=[];for(let d=1;d<=count;d++){let key=`${selectedMonth}-${String(d).padStart(2,'0')}`,e=db.deliveries[key]?.[c.id],qty=e?.supplied?(+e.qty||0):0;cells.push(`<span class="mini-day ${qty?'served':''}"><b>${d}</b><i>${qty||'–'}</i></span>`)}return `<aside class="invoice-calendar"><b>Monthly jar calendar</b><div class="mini-calendar">${cells.join('')}</div></aside>`}
function invoiceHTML(c){let a=account(c),number=esc(billNo(c)),b=db.business,header=`<header class="invoice-header"><div><h1>${esc(b.name)}</h1><p>${esc(b.address)}<br>${esc(b.phone)}${b.gstin?`<br>GSTIN: ${esc(b.gstin)}`:''}</p></div><div><h2>${c.gstBilling?'TAX INVOICE':'WATER SUPPLY INVOICE'}</h2><b>${number}</b><p>Billing month: ${selectedMonth}</p></div></header><section class="bill-to"><b>Bill to: ${esc(c.name)}</b><br>${esc(c.address)} · ${esc(c.phone)}${c.gstBilling&&c.customerGstin?`<br>GSTIN: ${esc(c.customerGstin)}`:''}${c.gstBilling&&c.state?` · ${esc(c.state)}`:''}</section>`;let adjustments=`<div><span>Previous pending</span><b>${money(a.opening)}</b></div><div><span>Payments adjusted</span><b>− ${money(a.paid)}</b></div><div class="grand"><span>Final payable</span><b>${money(a.balance)}</b></div>`;if(c.gstBilling){let split=a.gstAmount/2,taxA=c.gstType==='IGST'?'IGST':'CGST',taxB=c.gstType==='IGST'?'—':'SGST',taxOne=c.gstType==='IGST'?a.gstAmount:split,taxTwo=c.gstType==='IGST'?0:split,sellerDetails=[['GSTIN',b.gstin],['PAN',b.pan],['State',b.state],['State code',b.stateCode],['Email',b.email],['Phone',b.phone]].filter(x=>x[1]),buyerDetails=[['GSTIN',c.customerGstin],['PAN',c.customerPan],['State',c.state],['State code',c.stateCode],['Email',c.customerEmail],['Phone',c.phone]].filter(x=>x[1]),details=rows=>`<dl>${rows.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>`;return `<article class="invoice-page gst-invoice reference-invoice"><div class="ref-brand-strip">${esc(b.name)}</div><div class="ref-title-row"><div><h1>TAX INVOICE</h1><div><b>Invoice No:</b> ${number}</div><div><b>Billing Month:</b> ${selectedMonth}</div></div></div><div class="ref-party-grid"><section><h3>Billed By</h3><strong>${esc(b.name)}</strong><p>${esc(b.address)}</p>${details(sellerDetails)}</section><section><h3>Billed To</h3><strong>${esc(c.name)}</strong><p>${esc(c.address)}</p>${details(buyerDetails)}</section></div><table class="ref-items"><thead><tr><th>Item</th><th>GST Rate</th><th>Quantity</th><th>Rate</th><th>Taxable</th><th>${taxA}</th><th>${taxB}</th><th>Total</th></tr></thead><tbody><tr><td><strong>RO water jar supply</strong><small>${selectedMonth}</small></td><td>${a.gstRate}%</td><td>${a.supplied} jars</td><td>${money(c.rate)}</td><td>${money(a.taxable)}</td><td>${money(taxOne)}</td><td>${taxTwo?money(taxTwo):'—'}</td><td><strong>${money(a.total)}</strong></td></tr></tbody></table><div class="ref-summary"><div class="ref-words"><span>Invoice Amount</span><strong>${money(a.total)}</strong><small>Tax invoice generated for the selected billing month</small></div><div class="ref-totals"><div><span>Taxable amount</span><b>${money(a.taxable)}</b></div>${c.gstType==='IGST'?`<div><span>IGST (${a.gstRate}%)</span><b>${money(a.gstAmount)}</b></div>`:`<div><span>CGST (${a.gstRate/2}%)</span><b>${money(split)}</b></div><div><span>SGST (${a.gstRate/2}%)</span><b>${money(split)}</b></div>`}<div class="total"><span>Total (INR)</span><b>${money(a.total)}</b></div>${adjustments}</div></div><div class="ref-bottom"><div><strong>Declaration</strong><p>This is a computer-generated tax invoice. Please verify GST details before filing.</p></div><div class="ref-sign"><strong>Authorised Signatory</strong><br>${esc(b.name)}</div></div><footer>Empty jars due: <b>${a.jarsDue}</b> · Powered by iluvinvoice.net</footer></article>`}return `<article class="invoice-page">${header}<table><thead><tr><th>Description</th><th>Supply days</th><th>Total jars</th><th>Rate</th><th>Amount</th></tr></thead><tbody><tr><td>RO water supply for ${selectedMonth}</td><td>${a.days}</td><td>${a.supplied}</td><td>${money(c.rate)}</td><td>${money(a.charge)}</td></tr></tbody></table><div class="invoice-total"><div><span>Current supply</span><b>${money(a.charge)}</b></div>${a.discount?`<div><span>Discount</span><b>− ${money(a.discount)}</b></div>`:''}${adjustments}</div>${monthCalendar(c)}<footer>Empty jars due: <b>${a.jarsDue}</b> · Powered by iluvinvoice.net</footer></article>`}
