function referenceWaterInvoiceV2(c){
  const b=db.business,a=account(c),monthLabel=new Intl.DateTimeFormat('en-IN',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${selectedMonth}-01T00:00:00Z`));
  const template=document.createElement('template');template.innerHTML=referenceWaterInvoice(c);
  const invoice=template.content.querySelector('.ref-water-invoice');
  invoice.querySelector('.ref-water-head p').innerHTML=`${esc(b.address||'').replace(/\n/g,'<br>')}${b.phone?`<br>Phone &nbsp;${esc(b.phone)}`:''}`;
  invoice.querySelector('.ref-water-id b').textContent=monthLabel;
  invoice.querySelector('.ref-water-items tbody tr:first-child td:first-child').textContent=`RO water supply for ${monthLabel}`;
  invoice.querySelector('.ref-water-calendar p').textContent=`${monthLabel} · ● delivered  – none`;
  invoice.querySelector('.ref-water-invoice footer span')?.remove();
  const footer=invoice.querySelector('footer');footer.querySelector('span')?.remove();
  const invoiceNumber=invoice.querySelector('.ref-water-id strong')?.textContent||'';
  const footerMeta=document.createElement('span');footerMeta.textContent=`Invoice ${invoiceNumber} · Powered by iluvinvoice.net`;footer.append(footerMeta);
  const summary=invoice.querySelector('.ref-water-summary');
  [...summary.children].find(node=>node.textContent.includes('Payments adjusted'))?.remove();
  summary.querySelector('.ref-jars')?.remove();
  const qr=summary.querySelector('.ref-upi');if(qr)qr.remove();
  const notes=invoice.querySelector('.ref-water-notes');notes.querySelectorAll('p').forEach((p,i)=>{if(i===0)p.textContent='Amount = jars delivered × rate per jar. Final payable includes previous pending and any extra charges, less discounts and payments received.';if(i===1)p.textContent='Calendar: ● delivered jars, – no delivery.'});
  const bottom=document.createElement('div');bottom.className=`ref-water-bottom${qr?'':' no-upi'}`;
  if(qr){const card=document.createElement('section');card.className='ref-upi-card';const image=qr.querySelector('img');card.innerHTML=`<h3>PAY VIA UPI</h3><div class="ref-upi-row"><div class="ref-upi-image"></div><div class="ref-upi-details"><small>Amount</small><strong>${money(Math.max(0,a.balance))}</strong><small>Payee</small><b>${esc(b.name)}</b><small>UPI ID</small><span>${esc(b.upi)}</span></div></div><p>Scan with any UPI app</p>`;card.querySelector('.ref-upi-image').append(image);bottom.append(card)}
  bottom.append(notes);invoice.querySelector('.ref-water-body').append(bottom);
  return invoice.outerHTML;
}
