function masterExcel(){let rows=activeCustomers().map(c=>{let a=account(c);return[c.name,c.phone||'',a.supplied,a.charge,a.paid,a.balance,a.jarsDue]}),sheets=[['Executive Summary',[['Month',selectedMonth],['Customers',activeCustomers().length],['Jars',rows.reduce((a,r)=>a+r[2],0)],['Billing',rows.reduce((a,r)=>a+r[3],0)],['Collected',rows.reduce((a,r)=>a+r[4],0)]]],['Customer 360',[['Name','Phone','Jars','Billing','Paid','Balance','Jars Due'],...rows]],['Daily Deliveries',[['Date','Customer','Jars','Returned','Collection'],...Object.entries(db.deliveries).filter(([d])=>d.startsWith(selectedMonth)).flatMap(([d,day])=>Object.entries(day).filter(([,e])=>e.supplied).map(([id,e])=>[d,db.customers.find(c=>c.id===id)?.name||'',+e.qty||0,+e.returned||0,+e.payment||0]))]],['Collections',[['Date','Customer','Type','Method','Amount'],...db.payments.filter(p=>p.date.startsWith(selectedMonth)).map(p=>[p.date,db.customers.find(c=>c.id===p.customerId)?.name||'',p.kind||'Payment',p.method,+p.amount||0])]],['Advance Wallet',[['Date','Customer','Amount'],...db.payments.filter(p=>p.kind==='Advance').map(p=>[p.date,db.customers.find(c=>c.id===p.customerId)?.name||'',+p.amount||0])]],['Jar Inventory',Object.entries(db.inventory).map(([k,v])=>[k,v])],['Expenses',[['Date','Note','Amount'],...db.expenses.filter(e=>e.date.startsWith(selectedMonth)).map(e=>[e.date,e.note,+e.amount||0])]],['Drivers',[['Name','Phone','Status'],...db.staff.map(d=>[d.name,d.phone,d.active===false?'Disabled':'Active'])]]];let xml=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">${sheets.map(([name,data])=>`<Worksheet ss:Name="${esc(name)}"><Table>${data.map(r=>`<Row>${r.map(xmlCell).join('')}</Row>`).join('')}</Table></Worksheet>`).join('')}</Workbook>`,blob=new Blob([xml],{type:'application/vnd.ms-excel'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`water-business-audit-${selectedMonth}.xml`;a.click();URL.revokeObjectURL(a.href)}
document.addEventListener('click',e=>{let p=e.target.closest('[data-page]');if(p){page=p.dataset.page;search='';render();return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id;if(a==='install'){if(installPrompt){installPrompt.prompt();installPrompt=null}else toast('Use browser menu → Add to Home Screen')}else if(a==='save-note'){db.notes[selectedDate]=$('#dailyNote').value;persist(true);toast('Note saved')}else if(a==='mark-regular'){for(let c of activeCustomers()){let x=entry(c.id);x.supplied=true;x.qty=+c.regularQty||1;x.status='Completed'}persist();render()}else if(a==='save-now'){persist(true);toast('Daily register saved')}else if(a==='toggle-supply'){let x=entry(id);x.supplied=!x.supplied;x.status=x.supplied?'Completed':'Pending';if(x.supplied&&!x.qty)x.qty=+(db.customers.find(c=>c.id===id)?.regularQty||1);persist();render()}else if(a==='step'){let x=entry(id),k=b.dataset.key;x[k]=Math.max(0,(+x[k]||0)+(+b.dataset.delta));if(k==='qty'&&x[k]>0){x.supplied=true;x.status='Completed'}persist();render()}else if(a==='customer-modal')customerModal(id);else if(a==='submit-customer')$('#customerForm').requestSubmit();else if(a==='payment-modal')paymentModal();else if(a==='submit-payment')$('#paymentForm').requestSubmit();else if(a==='close-modal')$('#modal').close();else if(a==='save-inventory'){persist(true);toast('Inventory saved')}else if(a==='save-settings')$('#settingsForm').requestSubmit();else if(a==='print-all')printCustomers();else if(a==='print-one')printCustomers([id]);else if(a==='whatsapp'){let c=db.customers.find(x=>x.id===id),ac=account(c),msg=encodeURIComponent(`Hello ${c.name}, your ${selectedMonth} water bill is ${money(ac.balance)}. Total jars: ${ac.supplied}. Thank you — ${db.business.name}`);window.open(`https://wa.me/${String(c.phone||'').replace(/\D/g,'')}?text=${msg}`,'_blank')}else if(a==='export-month'){csv(`water-billing-${selectedMonth}.csv`,[['Customer','Supply days','Jars','Returned','Current amount','Previous pending','Paid','Balance'],...activeCustomers().map(c=>{let x=account(c);return[c.name,x.days,x.supplied,x.returned,x.charge,x.opening,x.paid,x.balance]})])}else if(a==='export-customers'){csv('water-customers.csv',[['Name','Phone','Address','Route','Rate','Opening balance','Jars due'],...activeCustomers().map(c=>[c.name,c.phone,c.address,c.route,c.rate,c.opening,c.jarsDue])])}else if(a==='export-backup'){let blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),x=document.createElement('a');x.href=URL.createObjectURL(blob);x.download=`water-plant-backup-${today()}.json`;x.click();URL.revokeObjectURL(x.href)}else if(a==='ledger'){let c=db.customers.find(x=>x.id===id),x=account(c);modal(`${esc(c.name)} ledger`,`<div class="summary"><div class="summary-row"><span>Supply days</span><b>${x.days}</b></div><div class="summary-row"><span>Jars supplied</span><b>${x.supplied}</b></div><div class="summary-row"><span>Payments</span><b>${money(x.paid)}</b></div><div class="summary-row"><span>Balance</span><b>${money(x.balance)}</b></div></div>`)}else if(a==='expense-modal'){modal('Add expense',`<form id="expenseForm" class="form-grid"><div class="field"><label>Date</label><input type="date" name="date" value="${today()}"></div><div class="field"><label>Amount</label><input type="number" min="1" name="amount"></div><div class="field full"><label>Category / note</label><input name="note"></div></form>`,`<button class="btn primary" data-action="submit-expense">Save expense</button>`)}else if(a==='submit-expense')$('#expenseForm').requestSubmit()});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;render();let s=$('#search');s?.focus();s?.setSelectionRange(search.length,search.length)}if(e.target.id==='supplySearch'){supplySearch=e.target.value;render();let s=$('#supplySearch');s?.focus();s?.setSelectionRange(supplySearch.length,supplySearch.length)}if(e.target.dataset.entry){let x=entry(e.target.dataset.id);x[e.target.dataset.entry]=Math.max(0,+e.target.value||0);if(e.target.dataset.entry==='qty'&&x.qty){x.supplied=true;x.status='Completed'}persist()}if(e.target.dataset.inventory){db.inventory[e.target.dataset.inventory]=Math.max(0,+e.target.value||0);persist()}if(e.target.dataset.monthPending){db.monthlyPending[selectedMonth]??={};db.monthlyPending[selectedMonth][e.target.dataset.monthPending]=Math.max(0,+e.target.value||0);status('Saving…');persist()}});
document.addEventListener('change',e=>{if(e.target.id==='dayPicker'){selectedDate=e.target.value;render()}if(e.target.id==='monthPicker'){selectedMonth=e.target.value;supplyFrom=`${selectedMonth}-01`;supplyTo=`${selectedMonth}-${String(new Date(+selectedMonth.slice(0,4),+selectedMonth.slice(5,7),0).getDate()).padStart(2,'0')}`;render()}if(e.target.id==='supplyFrom'){supplyFrom=e.target.value;render()}if(e.target.id==='supplyTo'){supplyTo=e.target.value;render()}if(e.target.id==='reportFrom'){reportFrom=e.target.value;render()}if(e.target.id==='reportTo'){reportTo=e.target.value;render()}});
document.addEventListener('submit',e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target));if(e.target.id==='customerForm'){let c=db.customers.find(x=>x.id===f.id);let val={...f,rate:+f.rate||0,regularQty:+f.regularQty||0,opening:+f.opening||0,jarsDue:+f.jarsDue||0,active:true};if(c){if((+c.rate||0)!==val.rate)for(const day of Object.values(db.deliveries)){const e=day[c.id];if(e&&e.supplied&&!e.rate)e.rate=+c.rate||+db.business.defaultRate||0}Object.assign(c,val)}else{val.id=`C${Date.now()}`;db.customers.push(val)}$('#modal').close();persist(true);render();toast('Customer saved')}if(e.target.id==='paymentForm'){db.payments.unshift({id:`P${Date.now()}`,...f,amount:+f.amount||0});$('#modal').close();persist(true);render();toast('Payment recorded')}if(e.target.id==='settingsForm'){Object.assign(db.business,f,{defaultRate:+f.defaultRate||0});persist(true);render();toast('Settings saved')}if(e.target.id==='expenseForm'){db.expenses.unshift({id:`E${Date.now()}`,...f,amount:+f.amount||0});$('#modal').close();persist(true);render();toast('Expense saved')}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});if('serviceWorker'in navigator)navigator.serviceWorker.register('/water-sw.js').catch(()=>{});load();

document.addEventListener('change',e=>{let input=e.target.closest('[data-restore]');if(!input?.files[0])return;input.files[0].text().then(t=>{let j=JSON.parse(t);if(!j||!Array.isArray(j.customers)||typeof j.deliveries!=='object')throw Error('bad');if(!confirm(`Restore ${j.customers.length} customers from this backup? This replaces your current Water Plant data.`))return;db=merge(seed,j);persist(true);render();toast('Backup restored')}).catch(()=>toast('That file is not a valid Water Plant backup',true)).finally(()=>{input.value=''})});
